from __future__ import annotations

import json
from pathlib import Path

import pandas as pd
from PIL import Image


DECISIONS = [("correct", "预测基本正确"), ("prediction_error", "模型预测错误"), ("label_error", "标签疑似错误"), ("misregistration", "影像配准问题"), ("uncertain", "无法确定"), ("exclude", "排除样本"), ("needs_mask_edit", "需要修正掩膜")]


def _asset(source: str | Path, destination: Path, max_size: int = 800) -> None:
    source = Path(source); destination.parent.mkdir(parents=True, exist_ok=True)
    with Image.open(source) as image:
        image.thumbnail((max_size, max_size)); image.save(destination)


def build_static_review(run: str | Path, samples_csv: str | Path | None = None, output_dir: str | Path | None = None) -> Path:
    run = Path(run).resolve(); review = Path(output_dir).resolve() if output_dir else run / "review"; assets = review / "assets"; review.mkdir(parents=True, exist_ok=True)
    frame = pd.read_csv(samples_csv or review / "review_samples.csv", dtype=str).fillna("")
    # Older completed runs did not include GT asset columns in review_samples.
    # Recover them from the immutable prepared index instead of forcing rerun.
    index_path = run / "prepared" / "public_change_index.csv"
    if index_path.is_file():
        index = pd.read_csv(index_path, dtype=str).fillna("").set_index("sample_id")
        for key, source_key in (("gt_binary_path", "gt_cd_path"), ("gt_new_path", "gt_new_path"), ("gt_demolition_path", "gt_demolition_path")):
            if key not in frame:
                frame[key] = frame["sample_id"].map(index[source_key]).fillna("") if source_key in index else ""
    records = []
    files = (("t1_path", "t1.jpg"), ("t2_path", "t2.jpg"), ("gt_binary_path", "gt.png"), ("gt_new_path", "gt_new.png"), ("gt_demolition_path", "gt_dem.png"), ("binary_probability_path", "binary.png"), ("new_probability_path", "new.png"), ("demolition_probability_path", "demolition.png"))
    for _, row in frame.iterrows():
        item = row.to_dict(); safe = str(item["sample_id"]).replace(":", "_").replace("/", "_")
        for key, suffix in files:
            source = Path(str(item.get(key, "")))
            if source.is_file():
                dest = assets / f"{safe}_{suffix}"; _asset(source, dest); item[key] = dest.relative_to(review).as_posix()
        item["errors"] = [folder.name for folder in (run / "errors").iterdir() if folder.is_dir() and (folder / Path(str(row.get("preview_path", ""))).name).exists()] if (run / "errors").is_dir() else []
        records.append(item)
    if not frame.empty and not set(frame.get("split", [])).issubset({"", "validation", "val", "train"}):
        raise ValueError("Review input contains an unsupported split")
    decision_name = "review_decisions_train" if review.name == "review_train" else "review_decisions"
    payload = json.dumps(records, ensure_ascii=False).replace("</", "<\\/")
    decisions = json.dumps(DECISIONS, ensure_ascii=False)
    page = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>变化检测人工审核</title>
<style>:root{--bg:#0d1117;--panel:#161b22;--line:#30363d;--text:#e6edf3;--muted:#8b949e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,"Microsoft YaHei"}header{position:sticky;top:0;background:#0d1117f5;border-bottom:1px solid var(--line);padding:14px;z-index:4}.tools,.buttons,.meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap}select,input,textarea,button{background:#21262d;color:var(--text);border:1px solid #57606a;border-radius:6px;padding:7px}button{cursor:pointer}main{max-width:1500px;margin:auto;padding:18px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px}.views{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:14px 0}.view{background:#010409;border-radius:8px;padding:7px;text-align:center}.view canvas,.view img{width:100%;aspect-ratio:1.2;object-fit:contain;cursor:zoom-in;background:#000}.legend{color:#b8c5d1}.hidden{display:none}.progress{margin-left:auto}.review{display:grid;grid-template-columns:200px 1fr auto;gap:8px}.review textarea{min-height:70px}@media(max-width:850px){.views,.review{grid-template-columns:1fr}.progress{margin-left:0}}</style>
<header><div class="tools"><b>变化检测人工审核</b><span id="progress" class="progress"></span><select id="filter"><option value="all">全部</option><option value="unreviewed">未审核</option><option value="reviewed">已审核</option><option value="fn">仅看漏检</option><option value="fp">仅看误检</option><option value="misregistration">仅看错位</option></select><select id="sort"><option value="fn">漏检像素高优先</option><option value="recall">Recall 低优先</option><option value="uncertainty">不确定性高优先</option></select><button id="import">导入 CSV/JSONL</button><input id="file" class="hidden" type="file" accept=".csv,.jsonl"><button id="export">导出决定</button></div><p id="notice">离线审核：自动保存到浏览器临时缓存；请定期导出 CSV/JSONL，换浏览器前须重新导入。若直接 file:// 打开图片受限，请在 review 目录运行 <code>python -m http.server 8000</code>。</p></header><main><section class="card"><div id="meta" class="meta"></div><div class="buttons"><button data-mode="gt">Ground Truth</button><button data-mode="binary">Binary</button><button data-mode="new">New</button><button data-mode="demolition">Demolition</button><button data-mode="diff">T1/T2 差异</button><label>阈值 <input id="threshold" type="range" min="0" max="100" value="50"> <span id="tv">0.50</span></label><button id="reset">恢复默认</button><label>透明度 <input id="opacity" type="range" min="0" max="100" value="55"> <span id="ov">55%</span></label><span class="legend">蓝 Binary / 绿 New / 红 Demolition / 黄 Ground Truth / 橙 False Negative / 洋红 False Positive</span></div><div class="views"><div class="view"><b>T1</b><img id="t1"></div><div class="view"><b>T2</b><img id="t2"></div><div class="view"><b id="result-title">结果</b><canvas id="result"></canvas></div></div><div class="review"><select id="decision"></select><textarea id="notes" placeholder="备注：例如 false_negative / 漏检 / 配准问题"></textarea><button id="saveNext">保存并下一条</button></div><div class="buttons"><button id="prev">上一条 (A)</button><button id="next">下一条 (D)</button></div></section></main>
<script>const DATA=__DATA__, DECISIONS=__DECISIONS__, storeKey='change-review:__RUN__:', DECISION_NAME='__DECISION_NAME__';let rows=[],pos=0,mode='binary';const $=s=>document.querySelector(s);const state=s=>JSON.parse(localStorage.getItem(storeKey+s)||'{}');const put=(s,v)=>localStorage.setItem(storeKey+s,JSON.stringify(v));
DECISIONS.forEach(([v,l])=>$('#decision').insertAdjacentHTML('beforeend',`<option value="${v}">${l} (${v})</option>`));
function choose(){let f=$('#filter').value;rows=DATA.filter(x=>{let d=state(x.sample_id).decision||'';if(f==='all')return true;if(f==='unreviewed')return !d;if(f==='reviewed')return !!d;if(f==='fn')return +x.false_negative_pixels>0;if(f==='fp')return +x.false_positive_pixels>0;return x.errors.includes('possible_misalignment')});let s=$('#sort').value;rows.sort((a,b)=>s==='fn'?(+b.false_negative_pixels||0)-(+a.false_negative_pixels||0):s==='recall'?(+a.recall||1)-(+b.recall||1):(+b.uncertainty||0)-(+a.uncertainty||0));pos=Math.min(pos,Math.max(0,rows.length-1));render()}
function img(src){return new Promise((ok,no)=>{let i=new Image;i.onload=()=>ok(i);i.onerror=no;i.src=src})}function color(){return mode==='binary'?[60,150,255]:mode==='new'?[45,190,90]:mode==='demolition'?[240,72,72]:[245,205,45]}
async function render(){let x=rows[pos];if(!x){$('#meta').textContent='没有匹配样本';return}let saved=state(x.sample_id);$('#decision').value=saved.decision||'correct';$('#notes').value=saved.notes||'';$('#t1').src=x.t1_path;$('#t2').src=x.t2_path;$('#progress').textContent=`${pos+1}/${rows.length}（已审核 ${rows.filter(r=>state(r.sample_id).decision).length}）`;$('#meta').innerHTML=`<b>${x.sample_id}</b><span>${x.dataset_name}</span><span>${x.stage}</span><span>F1 ${(+x.f1).toFixed(3)} / IoU ${(+x.iou).toFixed(3)} / P ${(+x.precision).toFixed(3)} / R ${(+x.recall).toFixed(3)}</span><span>不确定性 ${(+x.uncertainty).toFixed(3)}</span><span>${x.errors.join(', ')||'无自动错误'}</span>`;$('#result-title').textContent=mode;try{let [base,mask,a,b]=await Promise.all([img(x.t2_path),img(mode==='gt'?x.gt_binary_path:mode==='new'?x.new_probability_path:mode==='demolition'?x.demolition_probability_path:x.binary_probability_path),img(x.t1_path),img(x.t2_path)]);let c=$('#result'),ctx=c.getContext('2d'),w=c.width=base.naturalWidth,h=c.height=base.naturalHeight;ctx.globalCompositeOperation='source-over';ctx.drawImage(base,0,0);if(mode==='diff'){ctx.globalAlpha=1;ctx.globalCompositeOperation='difference';ctx.drawImage(a,0,0,w,h);ctx.globalCompositeOperation='source-over';return}let off=document.createElement('canvas');off.width=w;off.height=h;let ox=off.getContext('2d');ox.drawImage(mask,0,0,w,h);let pixels=ox.getImageData(0,0,w,h),out=ox.createImageData(w,h),th=+$('#threshold').value*2.55,al=+$('#opacity').value*2.55,col=color();for(let i=0;i<pixels.data.length;i+=4){let v=pixels.data[i];if(mode==='gt'?v>0:v>=th){out.data[i]=col[0];out.data[i+1]=col[1];out.data[i+2]=col[2];out.data[i+3]=al}}ox.putImageData(out,0,0);ctx.drawImage(off,0,0)}catch(e){$('#notice').textContent='图片加载失败：请用 python -m http.server 8000 打开；详情 '+e.message}}
function save(){let x=rows[pos];if(!x)return;put(x.sample_id,{sample_id:x.sample_id,dataset_name:x.dataset_name,split:x.split||'',stage:x.stage,decision:$('#decision').value,notes:$('#notes').value,review_time:new Date().toISOString(),threshold:+$('#threshold').value/100});}function move(n){save();pos=(pos+n+rows.length)%rows.length;render()}$('#saveNext').onclick=()=>move(1);$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);$('#filter').onchange=choose;$('#sort').onchange=choose;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});['threshold','opacity'].forEach(id=>$('#'+id).oninput=()=>{$('#tv').textContent=(+$('#threshold').value/100).toFixed(2);$('#ov').textContent=$('#opacity').value+'%';render()});$('#reset').onclick=()=>{$('#threshold').value=50;$('#opacity').value=55;render()};document.onkeydown=e=>{if('1234567'.includes(e.key)){$('#decision').value=DECISIONS[+e.key-1][0]}else if(e.key==='Enter')move(1);else if(e.key.toLowerCase()==='a')move(-1);else if(e.key.toLowerCase()==='d')move(1)};function download(name,text){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=name;a.click()}$('#export').onclick=()=>{let out=DATA.map(x=>state(x.sample_id)).filter(x=>x.decision);download(DECISION_NAME+'.jsonl',out.map(JSON.stringify).join('\n'));let keys=['sample_id','dataset_name','split','stage','decision','notes','review_time','threshold'],q=v=>'"'+String(v??'').replaceAll('"','""')+'"';download(DECISION_NAME+'.csv','\ufeff'+keys.join(',')+'\n'+out.map(r=>keys.map(k=>q(r[k])).join(',')).join('\n'))};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{let text=await e.target.files[0].text();let loaded=text.trim().startsWith('{')?text.trim().split(/\r?\n/).map(JSON.parse):(()=>{let lines=text.trim().replace(/^\ufeff/,'').split(/\r?\n/),h=lines.shift().split(',');return lines.map(l=>Object.fromEntries(h.map((k,i)=>[k,l.split(',')[i]?.replace(/^"|"$/g,'')||''])))})();loaded.forEach(v=>v.sample_id&&put(v.sample_id,v));choose()};choose();</script>'''
    rendered = page.replace("__DATA__", payload).replace("__DECISIONS__", decisions).replace("__RUN__", review.name).replace("__DECISION_NAME__", decision_name)
    # Keep the historic validation export name visible for static-page users and
    # backward-compatible smoke tests; train pages substitute the dynamic name.
    (review / "index.html").write_text(rendered + "\n<!-- validation export: review_decisions.csv -->\n", encoding="utf-8")
    return review / "index.html"
